    CreateEnvironmentRequest.add_member(:federation_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: FederationMode, location_name: 'federationMode', traits: {"smithy.api#documentation" => "<p>Authentication mode for the environment.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>FEDERATED</code> - Users access FinSpace through Single Sign On (SSO) via your Identity provider.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LOCAL</code> - Users access FinSpace via email and password managed within the FinSpace environment.</p>\n            </li>\n         </ul>"}))
