    CreateEnvironmentRequest.add_member(:data_bundles, Smithy::Schema::Shapes::ShapeRef.new(shape: DataBundleArns, location_name: 'dataBundles', traits: {"smithy.api#documentation" => "<p>The list of Amazon Resource Names (ARN) of the data bundles to install. Currently supported data bundle ARNs:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>arn:aws:finspace:${Region}::data-bundle/capital-markets-sample</code> - Contains sample Capital Markets datasets, categories and controlled vocabularies.</p>\n            </li>\n            <li>\n               <p>\n                  <code>arn:aws:finspace:${Region}::data-bundle/taq</code> (default) - Contains trades and quotes data in addition to sample Capital Markets data.</p>\n            </li>\n         </ul>"}))
