    CreateKxChangesetRequest.add_member(:environment_id, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentId, location_name: 'environmentId', traits: {"smithy.api#documentation" => "<p>A unique identifier of the kdb environment.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
