    CreateKxChangesetResponse.add_member(:last_modified_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'lastModifiedTimestamp', traits: {"smithy.api#documentation" => "<p>The timestamp at which the changeset was updated in FinSpace. The value is determined as epoch time in milliseconds. For example, the value for Monday, November 1, 2021 12:00:00 PM UTC is specified as 1635768000000.</p>"}))
    CreateKxChangesetResponse.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: ChangesetStatus, location_name: 'status', traits: {"smithy.api#documentation" => "<p>Status of the changeset creation process.</p>\n         <ul>\n            <li>\n               <p>Pending – Changeset creation is pending.</p>\n            </li>\n            <li>\n               <p>Processing – Changeset creation is running.</p>\n            </li>\n            <li>\n               <p>Failed – Changeset creation has failed.</p>\n            </li>\n            <li>\n               <p>Complete – Changeset creation has succeeded.</p>\n            </li>\n         </ul>"}))
