    CreateKxDataviewRequest.add_member(:az_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: KxAzMode, location_name: 'azMode', traits: {"smithy.api#documentation" => "<p>The number of availability zones you want to assign per volume. Currently, FinSpace only supports <code>SINGLE</code> for volumes. This places dataview in a single AZ.</p>", "smithy.api#required" => {}}))
