    KxCacheStorageConfiguration.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: KxCacheStorageType, location_name: 'type', traits: {"smithy.api#documentation" => "<p>The type of cache storage. The valid values are: </p>\n         <ul>\n            <li>\n               <p>CACHE_1000 – This type provides at least 1000 MB/s disk access throughput. </p>\n            </li>\n            <li>\n               <p>CACHE_250 – This type provides at least 250 MB/s disk access throughput. </p>\n            </li>\n            <li>\n               <p>CACHE_12 – This type provides at least 12 MB/s disk access throughput. </p>\n            </li>\n         </ul>\n         <p>For cache type <code>CACHE_1000</code> and <code>CACHE_250</code> you can select cache size as 1200 GB or increments of 2400 GB. For cache type <code>CACHE_12</code> you can select the cache size in increments of 6000 GB.</p>", "smithy.api#required" => {}}))
