    KxCluster.add_member(:cluster_type, Smithy::Schema::Shapes::ShapeRef.new(shape: KxClusterType, location_name: 'clusterType', traits: {"smithy.api#documentation" => "<p>Specifies the type of KDB database that is being created. The following types are available: </p>\n         <ul>\n            <li>\n               <p>HDB – A Historical Database. The data is only accessible with read-only permissions from one of the FinSpace managed kdb databases mounted to the cluster.</p>\n            </li>\n            <li>\n               <p>RDB – A Realtime Database. This type of database captures all the data from a ticker plant and stores it in memory until the end of day, after which it writes all of its data to a disk and reloads the HDB. This cluster type requires local storage for temporary storage of data during the savedown process. If you specify this field in your request, you must provide the <code>savedownStorageConfiguration</code> parameter.</p>\n            </li>\n            <li>\n               <p>GATEWAY – A gateway cluster allows you to access data across processes in kdb systems. It allows you to create your own routing logic using the initialization scripts and custom code. This type of cluster does not require a  writable local storage.</p>\n            </li>\n            <li>\n               <p>GP – A general purpose cluster allows you to quickly iterate on code during development by granting greater access to system commands and enabling a fast reload of custom code. This cluster type can optionally mount databases including cache and savedown storage. For this cluster type, the node count is fixed at 1. It does not support autoscaling and supports only <code>SINGLE</code> AZ mode.</p>\n            </li>\n            <li>\n               <p>Tickerplant – A tickerplant cluster allows you to subscribe to feed handlers based on IAM permissions. It can publish to RDBs, other Tickerplants, and real-time subscribers (RTS). Tickerplants can persist messages to log, which is readable by any RDB environment. It supports only single-node that is only one kdb process.</p>\n            </li>\n         </ul>"}))
    KxCluster.add_member(:cluster_description, Smithy::Schema::Shapes::ShapeRef.new(shape: KxClusterDescription, location_name: 'clusterDescription', traits: {"smithy.api#documentation" => "<p>A description of the cluster.</p>"}))
    KxCluster.add_member(:release_label, Smithy::Schema::Shapes::ShapeRef.new(shape: ReleaseLabel, location_name: 'releaseLabel', traits: {"smithy.api#documentation" => "<p>A version of the FinSpace managed kdb to run.</p>"}))
    KxCluster.add_member(:volumes, Smithy::Schema::Shapes::ShapeRef.new(shape: Volumes, location_name: 'volumes', traits: {"smithy.api#documentation" => "<p>\nA list of volumes attached to the cluster.\n</p>"}))
    KxCluster.add_member(:initialization_script, Smithy::Schema::Shapes::ShapeRef.new(shape: InitializationScriptFilePath, location_name: 'initializationScript', traits: {"smithy.api#documentation" => "<p>Specifies a Q program that will be run at launch of a cluster. It is a relative path within\n      <i>.zip</i> file that contains the custom code, which will be loaded on\n      the cluster. It must include the file name itself. For example,\n      <code>somedir/init.q</code>.</p>"}))
    KxCluster.add_member(:execution_role, Smithy::Schema::Shapes::ShapeRef.new(shape: ExecutionRoleArn, location_name: 'executionRole', traits: {"smithy.api#documentation" => "<p>\n            An IAM role that defines a set of permissions associated with a cluster. These permissions are assumed when a cluster attempts to access another cluster.\n         </p>"}))
    KxCluster.add_member(:az_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: KxAzMode, location_name: 'azMode', traits: {"smithy.api#documentation" => "<p>The number of availability zones assigned per cluster. This can be one of the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>SINGLE</code> – Assigns one availability zone per cluster.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MULTI</code> – Assigns all the availability zones per cluster.</p>\n            </li>\n         </ul>"}))
    KxCluster.add_member(:availability_zone_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneId, location_name: 'availabilityZoneId', traits: {"smithy.api#documentation" => "<p>\n            The availability zone identifiers for the requested regions.\n         </p>"}))
    KxCluster.add_member(:last_modified_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'lastModifiedTimestamp', traits: {"smithy.api#documentation" => "<p>The last time that the cluster was modified. The value is determined as epoch time in milliseconds. For example, the value for Monday, November 1, 2021 12:00:00 PM UTC is specified as 1635768000000.</p>"}))
    KxCluster.add_member(:created_timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'createdTimestamp', traits: {"smithy.api#documentation" => "<p>The timestamp at which the cluster was created in FinSpace. The value is determined as epoch time in milliseconds. For example, the value for Monday, November 1, 2021 12:00:00 PM UTC is specified as 1635768000000.</p>"}))
    KxCluster.type = Types::KxCluster
    KxClusterCodeDeploymentConfiguration.add_member(:deployment_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: KxClusterCodeDeploymentStrategy, location_name: 'deploymentStrategy', traits: {"smithy.api#documentation" => "<p>\n        The type of deployment that you want on a cluster.\n        \n      </p>\n         <ul>\n            <li>\n               <p>ROLLING – This options updates the cluster by stopping the exiting q process and starting a new q process with updated configuration.</p>\n            </li>\n            <li>\n               <p>NO_RESTART – This option updates the cluster without stopping the running q process. It is only available for <code>GP</code> type cluster. This option is quicker as it reduces the turn around time to update configuration on a cluster. </p>\n               <p>With this deployment mode, you cannot update the <code>initializationScript</code> and <code>commandLineArguments</code> parameters.</p>\n            </li>\n            <li>\n               <p>FORCE – This option updates the cluster by immediately stopping all the running processes before starting up new ones with the updated configuration. </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    KxClusterCodeDeploymentConfiguration.type = Types::KxClusterCodeDeploymentConfiguration
